          "duration": { "type": "fixed", "seconds": 21600 },
          "startTrigger": { "type": "afterStep", "stepId": "lightSmoker" }
        },
        {
          "stepId": "wrap",
          "name": "Wrap the shoulder tightly in butcher paper",
          "task": "prep",
          "duration": { "type": "fixed", "seconds": 600 },
